steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "
      {
        issue(identifier: \"MOB-3\") {
          id
          identifier
          title
          labels(first: 50) {
            nodes {
              id
              name
            }
          }
        }
        issueLabels(filter: { name: { eq: \"Regression\" }, group: { name: { eq: \"Bug\" } } }) {
          nodes {
            id
            name
            group {
              name
            }
          }
        }
      }
    '
  }'
